#include "2mm.h"

void kernel_2mm(
    double alpha,
    double beta,
    double tmp[16][18],
    double A[16][22],
    double B[22][18],
    double C[18][24],
    double D[16][24])
{
    // Step 1: Compute tmp = A * B
    // tmp is 16x18, A is 16x22, B is 22x18
    for (int i = 0; i < 16; i++) {
        for (int j = 0; j < 18; j++) {
            double sum = 0.0;
            for (int k = 0; k < 22; k++) {
                sum += A[i][k] * B[k][j];
            }
            tmp[i][j] = sum;
        }
    }

    // Step 2: Compute D = alpha * tmp * C + beta * D
    // tmp is 16x18, C is 18x24, D is 16x24
    for (int i = 0; i < 16; i++) {
        for (int j = 0; j < 24; j++) {
            double sum = 0.0;
            for (int k = 0; k < 18; k++) {
                sum += tmp[i][k] * C[k][j];
            }
            D[i][j] = alpha * sum + beta * D[i][j];
        }
    }
}
